// Fixed-seed, seven native opponents in the real shared Bullet world.
#include "race_ai.hpp"
#include "simulation.hpp"
#include "course_ui.hpp"
#include <iostream>
using namespace ofo;
int main(int argc,char**argv){try{if(argc<2)return 2;Resources resources(argv[1]);std::string stage=argc>3?argv[3]:"tracks/forest/forest1/a";float seconds=argc>4?std::stof(argv[4]):180;auto course=race_course(resources,stage);auto route=race_ai_route(course);auto roster=load_race_opponents(resources,1,argc>5?std::stoi(argv[5]):3,1,7,stage);auto geometry=load_geometry(resources,stage_geometry(stage),stage);auto player=load_vehicle(resources,3,argc>2?argv[2]:"");auto spawn=load_spawn(resources,stage);spawn[12]+=80;Simulation sim(geometry,player,spawn);sim.set_opponents(roster,route);CourseDirector director(course,8,1,7);std::vector<double>sum(7),low(7),peak(7),distance(7),lastspeed(7);std::vector<Vec>last(7);std::vector<uint64_t>recover(7);std::vector<int>collisions(7);std::vector<double>lap(7);for(size_t j=0;j<7;++j)last[j]={roster[j].spawn[12],roster[j].spawn[13],roster[j].spawn[14]};
 for(int k=0;k<int(seconds*100);++k){sim.step({});auto s=sim.state();std::vector<CoursePose>poses{{s.car,s.speed*3.6,s.driver_ejected}};for(size_t j=0;j<7;++j){auto&o=s.opponents->at(j);poses.push_back({o.car,o.speed*3.6,false});double v=std::abs(o.speed);sum[j]+=v;low[j]+=v<1.2?.01:0;peak[j]=std::max(peak[j],v);Vec p{o.car[12],o.car[13],o.car[14]};if(o.recovery_generation==recover[j])distance[j]+=length(p-last[j]);last[j]=p;recover[j]=o.recovery_generation;/* sharp physical speed losses are counted as impact proxies, not unique contact manifolds */if(lastspeed[j]-v>2)++collisions[j];lastspeed[j]=v;}director.update(.01,poses);for(size_t j=0;j<7;++j){if(director.finished(j+1)&&lap[j]==0)lap[j]=(k+1)*.01;}}
 Json out={{"seconds",seconds},{"stage",stage},{"handicap",argc>5?std::stoi(argv[5]):3},{"collision_metric","speed loss >2m/s in one 10ms tick (impact proxy)"},{"bots",Json::array()}};for(size_t j=0;j<7;++j){auto&o=sim.state().opponents->at(j);out["bots"].push_back({{"id",j+1},{"mean_mps",sum[j]/(seconds*100)},{"peak_mps",peak[j]},{"travel_m",distance[j]},{"stall_seconds",low[j]},{"recoveries",recover[j]},{"impact_proxy_count",collisions[j]},{"lap_seconds",lap[j]},{"damage",o.damage}});}out["race"]=director.summary();std::cout<<out.dump(2)<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
